<?php declare(strict_types=1);
require __DIR__.'/../src/bootstrap.php';require __DIR__.'/../push-runtime/vendor/autoload.php';
use Kulturhus\Verein\{Database,ClubChat,PushNotifications};use Minishlink\WebPush\{VAPID,WebPush,Subscription};
