$db=\Kulturhus\Verein\Tests\MySqlFixture::connect(':memory:');Database::migrate($db);$db->exec("INSERT INTO clubs VALUES('a','A');INSERT INTO actors(id,club_id,role) VALUES('one','a','member'),('two','a','member'),('three','a','member')");$client=VAPID::createVapidKeys();$vapid=VAPID::createVapidKeys()+['subject'=>'https://example.invalid'];$sub=['endpoint'=>'https://fcm.googleapis.com/fcm/send/isolated-test','keys'=>['p256dh'=>$client['publicKey'],'auth'=>rtrim(strtr(base64_encode(random_bytes(16)),'+/','-_'),'=')]];$push=new PushNotifications($db,'two');$push->save($sub);ok($push->count()===1,'valid opt-in stored');denied(fn()=>PushNotifications::validate(array_replace($sub,['endpoint'=>'https://127.0.0.1/internal'])),'private network endpoint rejected');denied(fn()=>PushNotifications::validate(array_replace($sub,['endpoint'=>'https://fcm.googleapis.com.evil.invalid/send'])),'lookalike provider rejected');$c=new ClubChat($db,'one');$chat=$c->create('Chat',['two']);$c->send($chat,'Private contents',bin2hex(random_bytes(16)));$payload='';PushNotifications::dispatch($db,function($s,$p)use(&$payload){$payload=$p;return 'sent';});ok(!str_contains($payload,'Private contents')&&!str_contains($payload,'Chat"'),'payload excludes private content and group name');ok(str_contains($payload,'Neue Nachricht'),'generic notification generated');ok(PushNotifications::dispatch($db,fn()=>throw new RuntimeException())===0,'push not repeated');$c->send($chat,'Another',bin2hex(random_bytes(16)));$other=new ClubChat($db,'two');$other->read($chat,(int)$db->query('SELECT MAX(seq) FROM club_chat_messages')->fetchColumn());ok(PushNotifications::dispatch($db,fn()=>throw new RuntimeException())===0,'read messages do not push');$c->send($chat,'Old account',bin2hex(random_bytes(16)));(new PushNotifications($db,'three'))->save($sub);ok($push->count()===0,'shared browser switches account binding');ok((int)$db->query("SELECT COUNT(*) FROM push_deliveries WHERE state='pending'")->fetchColumn()===0,'account switch removes queued old hints');
$push->save($sub);$c->send($chat,'Leaving',bin2hex(random_bytes(16)));$other->leave($chat);ok(PushNotifications::dispatch($db,fn()=>throw new RuntimeException())===0,'former participant receives no push');
