$encrypted=false;$web=new WebPush(['VAPID'=>$vapid],[],10,['allow_redirects'=>false,'handler'=>function($request,$options)use(&$encrypted){$encrypted=$request->getHeaderLine('Content-Encoding')==='aes128gcm'&&str_starts_with($request->getHeaderLine('Authorization'),'vapid ')&&!str_contains((string)$request->getBody(),'Generic test');return new \GuzzleHttp\Promise\FulfilledPromise(new \GuzzleHttp\Psr7\Response(201));}]);$report=$web->sendOneNotification(Subscription::create(PushNotifications::validate($sub)),'Generic test');ok($encrypted&&$report->isSuccess(),'real VAPID signature and encrypted provider request generated');ok(!(\Kulturhus\Verein\Tests\MySqlFixture::foreignKeyErrors($db)[0]??false),'push data integrity');
